result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/arm.js", "content": "import * as THREE from 'three';

/**
 * Build a skeletal robot arm as a chain of THREE.Bone nodes:
 *
 *   root (origin, zero-length base segment / shoulder pivot)
 *    └─ shoulder at (0, 0, 0)
 *        └─ elbow at (0, lengths[0], 0)
 *            └─ wrist at (0, lengths[1], 0)
 *                └─ tip at (0, last length, 0)
 *
 * Each child bone sits at (0, parentSegmentLength, 0); `root` is the base
 * pivot with no segment of its own, so the shoulder joint sits at the
 * origin and rotating it sweeps the whole arm.
 *
 * @param {number[]} segmentLengths - lengths of the arm segments
 * @returns {{ group: THREE.Group, root: THREE.Bone, shoulder: THREE.Bone,
 *             elbow: THREE.Bone, wrist: THREE.Bone, tip: THREE.Bone }}
 */
export function buildArm(segmentLengths) {
  if (!Array.isArray(segmentLengths) || segmentLengths.length < 3) {
    throw new Error('buildArm expects an array of at least 3 segment lengths');
  }

  const group = new THREE.Group();

  const root = new THREE.Bone();
  root.name = 'root';
  root.position.set(0, 0, 0);

  const shoulder = new THREE.Bone();
  shoulder.name = 'shoulder';
  // Root is the base pivot (segment length 0), so the shoulder joint sits
  // at the origin; its rotation swings every segment below it.
  shoulder.position.set(0, 0, 0);

  const elbow = new THREE.Bone();
  elbow.name = 'elbow';
  elbow.position.set(0, segmentLengths[0], 0);

  const wrist = new THREE.Bone();
  wrist.name = 'wrist';
  wrist.position.set(0, segmentLengths[1], 0);

  const tip = new THREE.Bone();
  tip.name = 'tip';
  tip.position.set(0, segmentLengths[segmentLengths.length - 1], 0);

  root.add(shoulder);
  shoulder.add(elbow);
  elbow.add(wrist);
  wrist.add(tip);

  group.add(root);

  return { group, root, shoulder, elbow, wrist, tip };
}

/**
 * Pose the arm by setting each bone's rotation around the Z axis.
 *
 * @param {{ shoulder: THREE.Bone, elbow: THREE.Bone, wrist: THREE.Bone }} arm
 * @param {{ shoulderZ?: number, elbowZ?: number, wristZ?: number }} pose
 */
export function poseArm(
  arm,
  { shoulderZ = 0, elbowZ = 0, wristZ = 0 } = {}
) {
  arm.shoulder.rotation.z = shoulderZ;
  arm.elbow.rotation.z = elbowZ;
  arm.wrist.rotation.z = wristZ;
  return arm;
}

/**
 * World-space position of the arm's tip bone (wrist end point).
 * Updates the world matrices before reading the position.
 *
 * @param {{ group: THREE.Group, tip: THREE.Bone }} arm
 * @returns {THREE.Vector3} tip position in world space
 */
export function tipPosition(arm) {
  arm.group.updateMatrixWorld(true);
  return arm.tip.getWorldPosition(new THREE.Vector3());
}
"})
