result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/arm.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildArm, poseArm, tipPosition } from '../src/arm.js';

const LENGTHS = [2, 2, 1];
const EPS = 1e-6;

describe('buildArm', () => {
  it('creates the named bone hierarchy wrapped in a Group', () => {
    const arm = buildArm(LENGTHS);

    expect(arm.group).toBeInstanceOf(THREE.Group);
    for (const name of ['root', 'shoulder', 'elbow', 'wrist', 'tip']) {
      expect(arm[name]).toBeInstanceOf(THREE.Bone);
      expect(arm[name].name).toBe(name);
    }

    expect(arm.root.parent).toBe(arm.group);
    expect(arm.shoulder.parent).toBe(arm.root);
    expect(arm.elbow.parent).toBe(arm.shoulder);
    expect(arm.wrist.parent).toBe(arm.elbow);
    expect(arm.tip.parent).toBe(arm.wrist);
  });

  it('has depth 4 from root to tip', () => {
    const arm = buildArm(LENGTHS);

    let depth = 0;
    let node = arm.tip;
    while (node !== arm.root) {
      node = node.parent;
      depth++;
    }
    expect(depth).toBe(4);
  });

  it('positions each child bone at (0, parentSegmentLength, 0)', () => {
    const arm = buildArm(LENGTHS);

    expect(arm.shoulder.position.toArray()).toEqual([0, 0, 0]);
    expect(arm.elbow.position.toArray()).toEqual([0, LENGTHS[0], 0]);
    expect(arm.wrist.position.toArray()).toEqual([0, LENGTHS[1], 0]);
    expect(arm.tip.position.toArray()).toEqual([0, LENGTHS[2], 0]);
  });
});

describe('poseArm forward kinematics vs analytic 2D solution', () => {
  it('with all angles 0 the tip is at (0, 5, 0)', () => {
    const arm = buildArm(LENGTHS);
    poseArm(arm, {});
    const p = tipPosition(arm);

    expect(p.x).toBeCloseTo(0, 6);
    expect(p.y).toBeCloseTo(5, 6);
    expect(p.z).toBeCloseTo(0, 6);
  });

  it('with shoulderZ = -PI/2 the tip is at (5, 0, 0)', () => {
    const arm = buildArm(LENGTHS);
    poseArm(arm, { shoulderZ: -Math.PI / 2 });
    const p = tipPosition(arm);

    expect(p.x).toBeCloseTo(5, EPS);
    expect(p.y).toBeCloseTo(0, EPS);
    expect(p.z).toBeCloseTo(0, EPS);
  });

  it('with shoulderZ = elbowZ = -PI/4 matches closed-form cos/sin sum', () => {
    const [L0, L1, L2] = LENGTHS;
    const thS = -Math.PI / 4;
    const thE = -Math.PI / 4;

    const expectedX = -L0 * Math.sin(thS) - (L1 + L2) * Math.sin(thS + thE);
    const expectedY = L0 * Math.cos(thS) + (L1 + L2) * Math.cos(thS + thE);

    const arm = buildArm(LENGTHS);
    poseArm(arm, { shoulderZ: thS, elbowZ: thE });
    const p = tipPosition(arm);

    expect(Math.abs(p.x - expectedX)).toBeLessThan(EPS);
    expect(Math.abs(p.y - expectedY)).toBeLessThan(EPS);
    expect(Math.abs(p.z)).toBeLessThan(EPS);
  });
});
"})
